import React from 'react';
import { Result, Button } from 'antd';

const SsoMessage = ({ message, status }) => {
  const closeWindow = () => {
    window.close()
  }
  return <div>
    { status === 'success' ? <Result
    status="success"
    title={message}
    subTitle="SSO has been successfully configured. You can now enable SSO from the dashboard."
    extra={[
      <Button type="primary" key="done" onClick={() => closeWindow()}>
        Done
      </Button>
    ]}
  /> :
  <Result
    status="error"
    title={message}
    extra={[
      <Button type="primary" key="done" onClick={() => closeWindow()}>
        Close
      </Button>
    ]}
  />}
  </div>
}

export default SsoMessage;